steps.script:
var m = tree.current_scene
var tb = m.get_node('TouchToolbar')
return tb.get_index() == m.get_node('BoardRoot').get_index() + 1 and tb.find_child('Touch_Board', true, false) != null and tb.find_child('Touch_All', true, false) != null and tb.find_child('Touch_Multi', true, false) != null

for il in tree.current_scene.find_children('*', 'ItemList', true, false):
	if not il.is_visible_in_tree():
		continue
	for i in il.item_count:
		if il.get_item_text(i).begins_with('Painboss'):
			var r = il.get_item_rect(i)
			TouchInputAdapter.inject_tap(il.get_global_transform_with_canvas() * (r.position + r.size * 0.5))
			return true
return false

var br = tree.current_scene.get_node('BoardRoot')
var a = br.get_global_transform_with_canvas() * Vector2(1240.0, 1640.0)
TouchInputAdapter.set_meta('a', a)
TouchInputAdapter.inject_touch(0, a, true)
return true

var br = tree.current_scene.get_node('BoardRoot')
var a = TouchInputAdapter.get_meta('a')
var b = br.get_global_transform_with_canvas() * Vector2(1300.0, 1700.0)
TouchInputAdapter.set_meta('b', b)
for k in range(1, 13):
	TouchInputAdapter.inject_drag(0, a.lerp(b, k / 12.0))
return true

var br = tree.current_scene.get_node('BoardRoot')
var b = TouchInputAdapter.get_meta('b')
var c = br.get_global_transform_with_canvas() * Vector2(1420.0, 1820.0)
TouchInputAdapter.set_meta('c', c)
for k in range(1, 13):
	TouchInputAdapter.inject_drag(0, b.lerp(c, k / 12.0))
return true
